head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var obj1 = {
        "label": "New1",
        "title": "dataObject1",
        "openAction": "exist",
        "closable": "true"
    };
    var obj2 = {
        "src": "tabControll_spinner_style_WESD-167_(WSQ-4347)_child1.xml",
        "frameMode": "wframePreload",
        "scope": true,
        "alwaysDraw": "true",
        "dataObject": {
            "type": "json",
            "name": "tabParam",
            "data": {}
        }
    };
    tabControl1.addTab("cmcm011a", obj1, obj2);
};
scwin.trigger2_onclick = function(e) {
    var obj1 = {
        "label": "New2",
        "title": "dataObject2",
        "openAction": "exist",
        "closable": "true"
    };
    var obj2 = {
        "src": "tabControll_spinner_style_WESD-167_(WSQ-4347)_child2.xml",
        "frameMode": "wframePreload",
        "scope": true,
        "alwaysDraw": "true",
        "dataObject": {
            "type": "json",
            "name": "tabParam",
            "data": {}
        }
    };
    tabControl1.addTab("cmcm011b", obj1, obj2);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1_tab_cmcm011b').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_contents_cmcm011b_body_spinner1___input').style.width != '0px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
